LUA_FIXTURE = "\nnow = 1000\nSCRIPT_PATH = 'face/aod15/'\nhistory = {}\ntimers = {}\ndelete_handler = nil\nimage_alive = true\nos.time = function() return now end\nos.execute = function() error('Shell must not run') end\nio.open = function() error('Filesystem must not be touched') end\nlocal image = {}\nfunction image:set(p)\n    assert(image_alive, 'Deleted image accessed')\n    assert(p.src:match('f%d%d%d%.png$'))\n    if image_fail then error('Image load failed') end\n    history[#history + 1] = tonumber(p.src:match('f(%d%d%d)%.png$'))\nend\nfunction image:invalidate() assert(image_alive) end\nfunction image:onevent(code, cb) delete_handler = cb end\nfunction image:anim(p)\n    return {set = function(self, values) end}\nend\nlvgl = {IMG_ZOOM_NONE = 256, EVENT = {DELETE = 33}}\nfunction lvgl.Image(_, p)\n    history[#history + 1] = tonumber(p.src:match('f(%d%d%d)%.png$'))\n    return image\nend\nfunction lvgl.Timer(p)\n    if timer_fail then error('No memory') end\n    local t = {period = p.period, paused = p.paused, cb = p.cb, deleted = false}\n    function t:set(values)\n        assert(not self.deleted)\n        for k, v in pairs(values) do self[k] = v end\n    end\n    function t:pause() self.paused = true end\n    function t:resume() self.paused = false end\n    function t:ready() end\n    function t:delete() self.deleted = true; self.paused = true end\n    timers[#timers + 1] = t\n    return t\nend\npackage.preload.lvgl = function() return lvgl end\nfunction tick(n)\n    local t = timers[1]\n    for i = 1, n do\n        if not t.paused and not t.deleted then t.cb(t) end\n    end\nend\nfunction last_frame() return history[#history] end\n"
